        console.log("[React App] Mounting single-page dashboard...");
        const { useState, useEffect, useRef } = React;

        // Backend API base.
        // When this page is served by the FastAPI backend (production / Indian-cloud
        // deploy), the API lives on the SAME origin, so we use relative URLs and the
        // app works behind any domain with no code change. When opened from a
        // separate static dev server (e.g. http.server on :5500) or file://, we fall
        // back to the local FastAPI port.
        const API_BASE = (function () {
            const origin = window.location.origin || '';
            const isStandaloneDev = origin.includes(':5500') || origin.startsWith('file');
            if (origin.startsWith('http') && !isStandaloneDev) return origin;
            return 'http://127.0.0.1:8000';
        })();
        const TOKEN_KEY = 'navrist_token';

        // Shared, deduped live-quote fetch. Every ratio card + both live-price
        // components used to call /api/quote independently — opening one report
        // page fired 15+ near-simultaneous requests for the SAME symbol, which is
        // what was tripping Angel One's "Access denied because of exceeding
        // access rate". Callers within QUOTE_DEDUPE_MS of each other for the same
        // symbol now share a single in-flight request/result instead of each
        // firing their own.
        const QUOTE_DEDUPE_MS = 5000;
        const _quoteCache = new Map(); // symbol -> { promise, timestamp }
        function fetchQuoteShared(symbol, token) {
            const now = Date.now();
            const cached = _quoteCache.get(symbol);
            if (cached && (now - cached.timestamp) < QUOTE_DEDUPE_MS) {
                return cached.promise;
            }
            const promise = fetch(`${API_BASE}/api/quote?symbol=${encodeURIComponent(symbol)}`, {
                headers: { 'Authorization': `Bearer ${token}` }
            }).then(r => (r.ok ? r.json() : null));
            _quoteCache.set(symbol, { promise, timestamp: now });
            return promise;
        }

        // Live-polling quote hook for every Market-Price-per-Share-based ratio
        // card (P/E, P/B, P/S, Dividend/Earnings/FCF Yield, EV/EBITDA, EV/Sales,
        // EV/FCF, PEG, Price-to-Cash-Flow, Graham Number, Altman Z-Score). Those
        // cards used to fetch the quote ONCE inside the same Promise.all as
        // their (slow-changing) statement-based fields, so the price shown
        // stayed frozen at whatever it was on page load — never updating again
        // even as the live market price moved, unless the user switched symbols
        // and back. This polls independently on the same 20s cadence as
        // DashHeader's own live price, so every MPS-based ratio recomputes
        // itself as the market moves, without re-triggering those cards'
        // (unrelated, unchanged) statement-data loading state.
        function useLiveQuote(symbol) {
            const [quote, setQuote] = useState(null);
            useEffect(() => {
                if (!symbol) { setQuote(null); return; }
                let active = true;
                const token = localStorage.getItem(TOKEN_KEY);
                const poll = () => {
                    fetchQuoteShared(symbol, token).then(d => { if (active && d) setQuote(d); }).catch(() => {});
                };
                poll();
                const id = setInterval(poll, 20000);
                return () => { active = false; clearInterval(id); };
            }, [symbol]);
            return quote;
        }

        // Animated count-up for headline numbers (quality score, etc.).
        const CountUp = ({ value, decimals = 0, suffix = '', className }) => {
            const [display, setDisplay] = useState(0);
            useEffect(() => {
                const to = Number(value);
                if (isNaN(to)) { setDisplay(0); return; }
                let raf;
                const dur = 900, start = performance.now();
                const tick = (t) => {
                    const p = Math.min(1, (t - start) / dur);
                    const eased = 1 - Math.pow(1 - p, 3);
                    setDisplay(to * eased);
                    if (p < 1) raf = requestAnimationFrame(tick);
                };
                raf = requestAnimationFrame(tick);
                return () => cancelAnimationFrame(raf);
            }, [value]);
            return <span className={className}>{display.toLocaleString('en-IN', { minimumFractionDigits: decimals, maximumFractionDigits: decimals })}{suffix}</span>;
        };

        // Searchable index of everything in the dashboard. Each entry maps search
        // terms -> the section tab + sub-tab to open, a breadcrumb path, and an
